def shortest_cut_to_multiple(lots, p):
    need = sum(lots) % p
    if need == 0:
        return 0
    first = {0: -1}
    run = 0
    best = len(lots)
    for i, x in enumerate(lots):
        run = (run + x) % p
        want = (run - need) % p
        if want in first:
            best = min(best, i - first[want])
        first.setdefault(run, i)
    return -1 if best == len(lots) else best

def shortest_cut_to_multiple(lots, p):
    n = len(lots)
    total = sum(lots)
    if total % p == 0:
        return 0
    for length in range(1, n):
        s = sum(lots[:length])
        for start in range(n - length + 1):
            if start:
                s += lots[start + length - 1] - lots[start - 1]
            if (total - s) % p == 0:
                return length
    return -1
